alter table public.routine_bundles enable row level security; alter table public.routine_bundle_steps enable row level security; drop policy if exists routine_bundles_select_own on public.routine_bundles; create policy routine_bundles_select_own on public.routine_bundles for select to authenticated using ((select auth.uid())=user_id); drop policy if exists routine_bundle_steps_select_own on public.routine_bundle_steps; create policy routine_bundle_steps_select_own on public.routine_bundle_steps for select to authenticated using ((select auth.uid())=user_id); revoke all on public.routine_bundles from anon,authenticated; revoke all on public.routine_bundle_steps from anon,authenticated; grant select on public.routine_bundles to authenticated; grant select on public.routine_bundle_steps to authenticated; grant all on public.routine_bundles to service_role; grant all on public.routine_bundle_steps to service_role;
